insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_entertainment','entertainment','noun','things such as films, music and games that people watch, play or listen to for enjoyment','[{"senseId":"entertainment_1","meaning":"things such as films, music and games that people watch, play or listen to for enjoyment","acceptedParaphrases":["amusement","things people watch for fun"],"masteryContexts":[{"contextId":"u2_01_entertainment_meaning","text":"The hotel offers live music and other entertainment every evening.","meaning":"shows, music or activities that people enjoy","wrongMeanings":["meals and drinks that guests order","rooms and services that guests book","rules and notices that guests read"]},{"contextId":"u2_01_entertainment_paraphrase","text":"Her grandparents saw the cinema as the main entertainment in the town.","meaning":"something people do for enjoyment","wrongMeanings":["something people do to earn money","something people do to stay healthy","something people do to learn a skill"]}],"situationDistractors":["The family spent the evening reading the news and checking the weather forecast.","A reporter interviewed the mayor about the new road.","Students stayed in the library to finish their history essays.","The students spent the whole lunch break sitting quietly in the library preparing for their geography test.","A local company offered a discount on school uniforms for families who live near the new campus.","The council announced that the main road would be closed for repairs until the end of the month."],"gapDistractors":[{"contextId":"u2_01_entertainment_gap_1","answer":"entertainment","wrong":["exercise","shopping","study"]},{"contextId":"u2_01_entertainment_gap_2","answer":"entertainment","wrong":["exercise","transport","shopping"]},{"contextId":"u2_01_entertainment_gap_3","answer":"entertainment","wrong":["catering","accommodation","transport"]}],"spellingErrors":["entertainmant","entertaiment","enterteinment","entertianment","entertainement","entertainmeant"],"wordFamilyForms":[{"form":"entertainment","partOfSpeech":"noun","example":"Live music was the main entertainment at the school festival.","pedagogicallyUseful":true},{"form":"entertain","partOfSpeech":"verb","example":"The magician managed to entertain hundreds of children for an hour.","pedagogicallyUseful":true},{"form":"entertaining","partOfSpeech":"adjective","example":"Her talks about travel are always entertaining and full of surprises.","pedagogicallyUseful":true},{"form":"entertainer","partOfSpeech":"noun","example":"The entertainer juggled flaming sticks at the end of the show.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_01_entertainment_passage_1","contextId":"u2_01_entertainment_gap_1","text":"After a tiring week of exams, Lena wanted something relaxing. She and her friends chose a film and a bag of popcorn, and the whole evening of ____ cost almost nothing.","answer":"entertainment"},{"passageId":"u2_01_entertainment_passage_2","contextId":"u2_01_entertainment_gap_2","text":"The new resort has a swimming pool, a cinema and live bands at night. Parents say the children never complain about boredom, because there is so much ____ on offer.","answer":"entertainment"}],"contextDependentParaphrases":[],"wrongParaphrases":["instruction","information","publicity"],"misleadingDistractors":["serious news reports","school lessons","private information"]}]'::jsonb,'["entertain","entertaining","entertainer"]'::jsonb,'["live entertainment","home entertainment","entertainment industry"]'::jsonb,'live'),
('vocab_access','access','noun','the right or ability to use something or to reach a place','[{"senseId":"access_1","meaning":"the right or ability to use something or to reach a place","acceptedParaphrases":["the ability or right to use","permission to use"],"masteryContexts":[{"contextId":"u2_02_access_meaning","text":"Only staff members have access to the server room.","meaning":"permission or the right to enter or use something","wrongMeanings":["a duty to guard or protect something","a plan to repair or replace something","a warning not to touch something"]},{"contextId":"u2_02_access_paraphrase","text":"Wheelchair users need easy access to every classroom.","meaning":"a way of reaching or entering a place","wrongMeanings":["a rule about who may teach in a place","a cost for building or cleaning a place","a view of the inside of a place"]}],"situationDistractors":["The shop closed early because of the storm.","A technician repaired the broken router yesterday.","The library moved to a bigger building.","The technician spent the morning replacing the old cables in the computer room.","The librarian asked the pupils to keep their voices down while others were revising.","Because the printer was out of ink, the teacher photocopied the worksheets in the staff room instead."],"gapDistractors":[{"contextId":"u2_02_access_gap_1","answer":"access","wrong":["speed","equipment","training"]},{"contextId":"u2_02_access_gap_2","answer":"access","wrong":["service","speed","equipment"]},{"contextId":"u2_02_access_gap_3","answer":"access","wrong":["service","equipment","speed"]}],"spellingErrors":["acess","acces","axcess","accses","acsess","accesss"],"wordFamilyForms":[{"form":"access","partOfSpeech":"noun","example":"Students need access to a quiet room when they revise.","pedagogicallyUseful":true},{"form":"accessible","partOfSpeech":"adjective","example":"The museum is accessible to visitors in wheelchairs.","pedagogicallyUseful":true,"altExample":"Public libraries should be accessible to everyone in the community."},{"form":"inaccessible","partOfSpeech":"adjective","example":"In winter, the mountain villages become inaccessible by road.","pedagogicallyUseful":true,"altExample":"Heavy snow left the remote cabin inaccessible for a week."}],"masteryPassages":[{"passageId":"u2_02_access_passage_1","contextId":"u2_02_access_gap_1","text":"Amira’s village has no broadband cable, so she cannot do her research at home. Every weekday she walks to the library, where she has free ____ to the computers and the wi-fi.","answer":"access"},{"passageId":"u2_02_access_passage_2","contextId":"u2_02_access_gap_2","text":"The school gave each pupil a password for the online library. Without it, nobody could get ____ to the e-books or the study guides.","answer":"access"}],"contextDependentParaphrases":[],"wrongParaphrases":["a limit on use","a fee for use","a record of use"],"misleadingDistractors":["permission to leave","a payment for using something","a report on something"]}]'::jsonb,'["accessible","inaccessible"]'::jsonb,'["internet access","easy access","gain access"]'::jsonb,'live'),
('vocab_device','device','noun','a small machine or piece of equipment made for a particular purpose, such as a phone or tablet','[{"senseId":"device_1","meaning":"a small machine or piece of equipment made for a particular purpose, such as a phone or tablet","acceptedParaphrases":["gadget","electronic tool"],"masteryContexts":[{"contextId":"u2_03_device_meaning","text":"You can charge this device in two hours.","meaning":"a small electronic machine","wrongMeanings":["a long wire that carries electricity","a socket fixed to a wall","a shop that repairs machines"]},{"contextId":"u2_03_device_paraphrase","text":"A simple device on the door warns you when it is open.","meaning":"a tool made for a specific purpose","wrongMeanings":["a plan for making a door safer","a rule about when a door must be shut","a person who guards the door"]}],"situationDistractors":["A mechanic spent the afternoon repairing the engine of the school bus.","The teacher handed out printed worksheets to every student.","A visitor asked how to find the science laboratory.","The student wrote a long email to the school office asking about the changes to the timetable.","The pupils waited in the hall while the teacher checked that every name on the list was spelled correctly.","On Friday afternoon, the whole class walked to the park to sketch trees for their art project."],"gapDistractors":[{"contextId":"u2_03_device_gap_1","answer":"device","wrong":["passport","sandwich","umbrella"]},{"contextId":"u2_03_device_gap_2","answer":"device","wrong":["uniform","dictionary","jacket"]},{"contextId":"u2_03_device_gap_3","answer":"device","wrong":["season","window","neighbour"]}],"spellingErrors":["divice","devic","deveice","devvice","deviec"],"masteryPassages":[{"passageId":"u2_03_device_passage_1","contextId":"u2_03_device_gap_1","text":"Phones, tablets and smartwatches all belong to the same group. Each one is a small electronic ____ that you can carry, charge and connect to the internet.","answer":"device"},{"passageId":"u2_03_device_passage_2","contextId":"u2_03_device_gap_2","text":"The factory makes tiny sensors for hospitals. Each ____ is smaller than a coin, but it can measure a patient’s heartbeat all day.","answer":"device"}],"contextDependentParaphrases":[],"wrongParaphrases":["cable","manual","technician"],"misleadingDistractors":["a rule that controls behaviour","a place where machines are made","a person who repairs machines"]}]'::jsonb,'[]'::jsonb,'["electronic device","mobile device","smart device"]'::jsonb,'live'),
('vocab_digital','digital','adjective','using electronic technology, especially computers and the internet, to store or send information','[{"senseId":"digital_1","meaning":"using electronic technology, especially computers and the internet, to store or send information","acceptedParaphrases":["electronic","computer-based"],"masteryContexts":[{"contextId":"u2_04_digital_meaning","text":"She keeps a digital copy of every important document.","meaning":"stored electronically on a computer or phone","wrongMeanings":["printed clearly on good paper","written carefully by hand","copied from an older book"]},{"contextId":"u2_04_digital_paraphrase","text":"Most photographers now use digital cameras instead of film.","meaning":"using electronic technology","wrongMeanings":["working with film and chemicals","made by hand in small workshops","sold only in specialist shops"]}],"situationDistractors":["The teacher wrote the homework on the whiteboard with a marker.","Students handed in handwritten essays on lined paper.","The museum displayed paintings from the nineteenth century.","The artist painted a huge mural on the wall of the school gym using bright colours and thick brushes.","The history teacher showed the class a collection of old coins that had been found near the river.","Everyone in the choir stood up and sang together at the end of the school concert."],"gapDistractors":[{"contextId":"u2_04_digital_gap_1","answer":"digital","wrong":["printed","traditional","handwritten"]},{"contextId":"u2_04_digital_gap_2","answer":"digital","wrong":["printed","physical","handwritten"]},{"contextId":"u2_04_digital_gap_3","answer":"digital","wrong":["printed","physical","traditional"]}],"spellingErrors":["digitel","digitall","digtal","dijital","digitale","degital"],"wordFamilyForms":[{"form":"digital","partOfSpeech":"adjective","example":"Most of the library’s records are now digital.","pedagogicallyUseful":true},{"form":"digitally","partOfSpeech":"adverb","example":"The photographs were digitally edited before they were printed.","pedagogicallyUseful":true,"altExample":"Tickets are now delivered digitally, so nobody needs to print them."},{"form":"digitise","partOfSpeech":"verb","example":"The museum plans to digitise its oldest maps so they can be viewed online.","pedagogicallyUseful":true,"altExample":"It takes weeks to digitise a large archive of photographs."}],"masteryPassages":[{"passageId":"u2_04_digital_passage_1","contextId":"u2_04_digital_gap_1","text":"Grandfather still keeps his photographs in heavy paper albums. His granddaughter has scanned every picture and stored a ____ version on her laptop, so the family can share them online.","answer":"digital"},{"passageId":"u2_04_digital_passage_2","contextId":"u2_04_digital_gap_2","text":"In many offices, paper letters have been replaced by emails and online forms. This shift to a ____ way of working saves space, but it also means everyone depends on reliable internet.","answer":"digital"}],"contextDependentParaphrases":[],"wrongParaphrases":["printed","handwritten","old-fashioned"],"misleadingDistractors":["made by hand","printed on paper","very old-fashioned"]}]'::jsonb,'["digitally","digitise"]'::jsonb,'["digital technology","digital age","digital skills"]'::jsonb,'live'),
('vocab_streaming','streaming','noun','playing video or music over the internet as it arrives, without downloading it first','[{"senseId":"streaming_1","meaning":"playing video or music over the internet as it arrives, without downloading it first","acceptedParaphrases":["online viewing","playing over the internet"],"masteryContexts":[{"contextId":"u2_05_streaming_meaning","text":"Music streaming means you never need to buy a CD.","meaning":"playing music over the internet without downloading it","wrongMeanings":["copying songs from a disc onto a computer","recording songs from the radio","buying songs one at a time from a shop"]},{"contextId":"u2_05_streaming_paraphrase","text":"Slow internet makes streaming difficult in rural areas.","meaning":"watching or listening online as the data arrives","wrongMeanings":["saving files to a device for later use","sending large files to other people","checking online messages every few minutes"]}],"situationDistractors":["Fans queued outside the shop to buy the new album on a disc.","She downloaded the film and saved it to her laptop before the flight.","The family recorded the football match on a video recorder.","The family drove for three hours to see the match at the new stadium.","Students queued at the canteen for lunch while the teacher called out each table number.","The pop singer signed hundreds of posters and photographs after her concert in the city centre."],"gapDistractors":[{"contextId":"u2_05_streaming_gap_1","answer":"streaming","wrong":["recording","television","copying"]},{"contextId":"u2_05_streaming_gap_2","answer":"streaming","wrong":["recording","television","printing"]},{"contextId":"u2_05_streaming_gap_3","answer":"streaming","wrong":["downloading","recording","television"]}],"spellingErrors":["streeming","streming","streamimg","streammng","streamin","streeaming"],"wordFamilyForms":[{"form":"streaming","partOfSpeech":"noun","example":"The rise of streaming has changed how teenagers watch television.","pedagogicallyUseful":true},{"form":"stream","partOfSpeech":"verb","example":"You can stream the concert live from your living room.","pedagogicallyUseful":true,"altExample":"Many families stream a film together on Friday evenings."},{"form":"streamer","partOfSpeech":"noun","example":"The streamer plays games online for thousands of viewers each evening.","pedagogicallyUseful":true,"altExample":"A popular streamer can earn money from advertisements and gifts from viewers.","note":"Thin family: only one derivative beyond stream/streaming, so it is flagged for teacher review."}],"masteryPassages":[{"passageId":"u2_05_streaming_passage_1","contextId":"u2_05_streaming_gap_1","text":"Instead of buying discs or waiting for a whole film to download, Ravi simply opens an app and presses play. This kind of ____ only works well when his internet connection is fast.","answer":"streaming"},{"passageId":"u2_05_streaming_passage_2","contextId":"u2_05_streaming_gap_2","text":"Cinema ticket sales have fallen for several years. Many viewers now prefer ____ services, which let them watch new series at home on any day they choose.","answer":"streaming"}],"contextDependentParaphrases":[],"wrongParaphrases":["file downloading","disc recording","message sending"],"misleadingDistractors":["copying files onto a memory stick","buying DVDs from a shop","sending messages to friends"]}]'::jsonb,'["stream","streamer"]'::jsonb,'["streaming service","music streaming","live streaming"]'::jsonb,'live'),
('vocab_relevant','relevant','adjective','connected to the subject being discussed, and so useful or important for it','[{"senseId":"relevant_1","meaning":"connected to the subject being discussed, and so useful or important for it","acceptedParaphrases":["connected","related"],"masteryContexts":[{"contextId":"u2_06_relevant_meaning","text":"Her experience is relevant to the job.","meaning":"connected to the matter and useful for it","wrongMeanings":["too limited to be of any use","far greater than anyone else’s","valued highly by her friends"]},{"contextId":"u2_06_relevant_paraphrase","text":"Please delete any information that is not relevant.","meaning":"connected to the topic being discussed","wrongMeanings":["available to anyone who asks","recently added to the page","difficult for readers to understand"]}],"situationDistractors":["The writer added a funny story that had nothing to do with the topic.","The student copied a paragraph without reading it.","The article was too long for the class to finish.","The students tidied the classroom, put the chairs away and switched off the lights before going home.","A famous author visited the school and signed copies of her latest book for pupils in the library.","The teacher praised the class for finishing the experiment early and cleaning all the equipment."],"gapDistractors":[{"contextId":"u2_06_relevant_gap_1","answer":"relevant","wrong":["general","additional","recent"]},{"contextId":"u2_06_relevant_gap_2","answer":"relevant","wrong":["general","recent","additional"]},{"contextId":"u2_06_relevant_gap_3","answer":"relevant","wrong":["recent","familiar","additional"]}],"spellingErrors":["relevent","relavant","revelant","relevat","relivant","relevaant"],"wordFamilyForms":[{"form":"relevant","partOfSpeech":"adjective","example":"Please include only information that is relevant to the question.","pedagogicallyUseful":true},{"form":"relevance","partOfSpeech":"noun","example":"The teacher asked her to explain the relevance of the example.","pedagogicallyUseful":true,"altExample":"The relevance of the statistics to the argument was unclear."},{"form":"irrelevant","partOfSpeech":"adjective","example":"Most of the comments online were irrelevant to the discussion.","pedagogicallyUseful":true,"altExample":"Spelling mistakes were irrelevant to the marking of the speaking test."}],"masteryPassages":[{"passageId":"u2_06_relevant_passage_1","contextId":"u2_06_relevant_gap_1","text":"Mr Okafor read the student’s essay carefully. Although the paragraph about her holiday was well written, it was not ____ to the question, so he advised her to remove it.","answer":"relevant"},{"passageId":"u2_06_relevant_passage_2","contextId":"u2_06_relevant_gap_2","text":"A strong report does not include every fact the writer found. It keeps only the ____ evidence and leaves out anything that does not bear on the question.","answer":"relevant"}],"contextDependentParaphrases":[],"wrongParaphrases":["popular","recent","difficult"],"misleadingDistractors":["difficult to understand","extremely popular","very recent"]}]'::jsonb,'["relevance","irrelevant"]'::jsonb,'["highly relevant","relevant information","no longer relevant"]'::jsonb,'live'),
('vocab_educator','educator','noun','a person whose job is to teach or train others','[{"senseId":"educator_1","meaning":"a person whose job is to teach or train others","acceptedParaphrases":["teacher","person who teaches"],"masteryContexts":[{"contextId":"u2_07_educator_meaning","text":"As an educator, she believes every child can succeed.","meaning":"a person who teaches","wrongMeanings":["a person who inspects schools","a person who writes textbooks","a person who studies at home"]},{"contextId":"u2_07_educator_paraphrase","text":"Any good educator tries to make lessons interesting for every student.","meaning":"someone whose job is to teach or train others","wrongMeanings":["someone whose job is to inspect school buildings","someone whose job is to write the exam papers","someone whose job is to manage the school budget"]}],"situationDistractors":["A student asked the librarian where to find a dictionary.","A parent collected her son from the school gates.","A visitor from the council inspected the school kitchen.","The bus driver waited at the gate while the students collected their bags and said goodbye.","The school nurse treated a student who had fallen over and hurt her knee in the playground.","A group of parents organised a cake sale to raise money for new playground equipment."],"gapDistractors":[{"contextId":"u2_07_educator_gap_1","answer":"educator","wrong":["engineer","architect","accountant"]},{"contextId":"u2_07_educator_gap_2","answer":"educator","wrong":["engineer","dentist","farmer"]},{"contextId":"u2_07_educator_gap_3","answer":"educator","wrong":["engineer","architect","accountant"]}],"spellingErrors":["educater","edukator","educatar","eductor","educaitor","edducator"],"wordFamilyForms":[{"form":"educator","partOfSpeech":"noun","example":"An experienced educator can explain a difficult idea in simple terms.","pedagogicallyUseful":true},{"form":"educate","partOfSpeech":"verb","example":"The campaign aims to educate teenagers about online safety.","pedagogicallyUseful":true,"altExample":"Parents and teachers must work together to educate young people."},{"form":"education","partOfSpeech":"noun","example":"Free education gives young people a chance to succeed.","pedagogicallyUseful":true,"altExample":"Access to good education should not depend on where you live."}],"masteryPassages":[{"passageId":"u2_07_educator_passage_1","contextId":"u2_07_educator_gap_1","text":"Mrs Zhang has spent thirty years in the classroom, planning lessons and guiding young people through their exams. Her pupils describe her as a patient and inspiring ____.","answer":"educator"},{"passageId":"u2_07_educator_passage_2","contextId":"u2_07_educator_gap_2","text":"The conference brought together head teachers, trainers and university lecturers. Each ____ in the audience shared ideas about how to help students learn more effectively.","answer":"educator"}],"contextDependentParaphrases":[],"wrongParaphrases":["inspector","librarian","caretaker"],"misleadingDistractors":["a student who studies at home","a person who owns a school","a person who inspects buildings"]}]'::jsonb,'["educate","education"]'::jsonb,'["experienced educator","qualified educator","dedicated educator"]'::jsonb,'live'),
('vocab_afford_2','afford','verb','to have enough money to buy or pay for something','[{"senseId":"afford_2_1","meaning":"to have enough money to buy or pay for something","acceptedParaphrases":["have enough money for","be able to pay for"],"masteryContexts":[{"contextId":"u2_08_afford_2_meaning","text":"Many students cannot afford the latest smartphone.","meaning":"have enough money to pay for","wrongMeanings":["be patient enough to wait for","be confident enough to try","be interested enough to read about"]},{"contextId":"u2_08_afford_2_paraphrase","text":"We can afford a short holiday, but not a long one.","meaning":"have enough money for","wrongMeanings":["be allowed to take","be forced to cancel","be eager to avoid"]}],"situationDistractors":["The family borrowed a laptop from a neighbour for a week.","The shop refused to give a refund on the broken tablet.","The shop assistant recommended a cheaper tablet to the customer.","The group decided to take the bus because the weather was too wet for a long walk.","The shop assistant wrapped the present carefully and tied a red ribbon around the box.","Students were allowed to wear sports clothes on the last day of term as a special treat."],"gapDistractors":[{"contextId":"u2_08_afford_2_gap_1","answer":"afford","wrong":["describe","translate","advertise"]},{"contextId":"u2_08_afford_2_gap_2","answer":"afford","wrong":["pretend","threaten","forget"]},{"contextId":"u2_08_afford_2_gap_3","answer":"afford","wrong":["sketch","photograph","advertise"]}],"spellingErrors":["aford","affored","afforde","afferd","afoord","affoard"],"wordFamilyForms":[{"form":"afford","partOfSpeech":"verb","example":"Few students can afford to buy every textbook they need.","pedagogicallyUseful":true},{"form":"affordable","partOfSpeech":"adjective","example":"The school offers affordable laptops to families on low incomes.","pedagogicallyUseful":true,"altExample":"Healthy food should be affordable for every family."},{"form":"unaffordable","partOfSpeech":"adjective","example":"For many households, high-speed internet is still unaffordable.","pedagogicallyUseful":true,"altExample":"Tickets for the concert were unaffordable for most students."}],"masteryPassages":[{"passageId":"u2_08_afford_2_passage_1","contextId":"u2_08_afford_2_gap_1","text":"Sam would love a new laptop for his studies. Unfortunately, the price is far higher than his savings, so he cannot ____ one this year.","answer":"afford"},{"passageId":"u2_08_afford_2_passage_2","contextId":"u2_08_afford_2_gap_2","text":"The family wants to replace their old computer, but bills have risen recently. They will wait until they can ____ a better one without taking out a loan.","answer":"afford"}],"contextDependentParaphrases":[],"wrongParaphrases":["borrow money for","refuse to pay for","offer a discount on"],"misleadingDistractors":["borrow from a friend","refuse to pay for","choose to buy"],"teacherNote":"Unit 2 item (afford_2), separate from Unit 1 afford; shares only the lexical spelling list."}]'::jsonb,'["affordable","unaffordable"]'::jsonb,'["can afford","barely afford","afford the cost"]'::jsonb,'live'),
('vocab_essential','essential','adjective','absolutely necessary; extremely important','[{"senseId":"essential_1","meaning":"absolutely necessary; extremely important","acceptedParaphrases":["absolutely necessary","vital"],"masteryContexts":[{"contextId":"u2_09_essential_meaning","text":"Sleep is essential for healthy growth.","meaning":"absolutely necessary","wrongMeanings":["pleasant but unimportant","common but unexplained","popular among teenagers"]},{"contextId":"u2_09_essential_paraphrase","text":"Take only the essential items when travelling light.","meaning":"so important that you cannot leave it out","wrongMeanings":["so valuable that it must be insured","so large that it is hard to carry","so new that it has not been tested"]}],"situationDistractors":["Students could choose between several optional clubs after school.","A teacher said the extra homework was a nice idea but not required.","The library offered a free newsletter to anyone who wanted one.","The class could choose any three of the five topics for their project, depending on their interests.","The shop sold many different types of bags, from small backpacks to large suitcases with wheels.","A new coffee machine was fitted in the staff room, and the teachers enjoyed trying different flavours."],"gapDistractors":[{"contextId":"u2_09_essential_gap_1","answer":"essential","wrong":["optional","convenient","popular"]},{"contextId":"u2_09_essential_gap_2","answer":"essential","wrong":["optional","convenient","popular"]},{"contextId":"u2_09_essential_gap_3","answer":"essential","wrong":["optional","unnecessary","decorative"]}],"spellingErrors":["essencial","esential","essentail","essensial","essentual","esssential"],"wordFamilyForms":[{"form":"essential","partOfSpeech":"adjective","example":"A charger is essential for anyone who travels with a phone.","pedagogicallyUseful":true},{"form":"essentially","partOfSpeech":"adverb","example":"The two apps are essentially the same, but one is free.","pedagogicallyUseful":true,"altExample":"The film is essentially a love story set in a futuristic city."},{"form":"essentials","partOfSpeech":"noun","example":"Pack the essentials first, such as your passport and tickets.","pedagogicallyUseful":true,"altExample":"The shop sells all the essentials, such as bread, milk and batteries."}],"masteryPassages":[{"passageId":"u2_09_essential_passage_1","contextId":"u2_09_essential_gap_1","text":"Before the long hike, the guide checked each rucksack. Water and warm clothing were ____, but the games console had to stay behind.","answer":"essential"},{"passageId":"u2_09_essential_passage_2","contextId":"u2_09_essential_gap_2","text":"Online banking relies on strong security. For this reason, a secure password is ____, and customers are told never to share it.","answer":"essential"}],"contextDependentParaphrases":[],"wrongParaphrases":["widely available","very expensive","quite useful"],"misleadingDistractors":["available to everyone","expensive and rare","recently invented"]}]'::jsonb,'["essentially","essentials"]'::jsonb,'["absolutely essential","essential equipment","essential skills"]'::jsonb,'live'),
('vocab_current_affairs','current affairs','noun','important news about politics, society and world events that are happening now','[{"senseId":"current_affairs_1","meaning":"important news about politics, society and world events that are happening now","acceptedParaphrases":["world news","recent events in the news"],"masteryContexts":[{"contextId":"u2_10_current_affairs_meaning","text":"He listens to a podcast on current affairs during his walk.","meaning":"news about politics and world events","wrongMeanings":["stories about sport and music","advice about money and health","lessons about history and languages"]},{"contextId":"u2_10_current_affairs_paraphrase","text":"Our class discussion on current affairs became very lively.","meaning":"events in the news now","wrongMeanings":["events planned for next year","events from a long time ago","events that happen at school"]}],"situationDistractors":["The history teacher described a battle from the sixteenth century.","A novelist read a chapter from her latest story.","The student wrote a diary entry about her weekend at home.","The class watched a documentary about life in the Roman army and then drew pictures of soldiers’ armour.","Students swapped recipes for their favourite meals and prepared a small cookbook for the school fair.","The principal reminded the school that the swimming gala would take place on the first Friday of next term."],"gapDistractors":[{"contextId":"u2_10_current_affairs_gap_1","answer":"current affairs","wrong":["historical events","fictional stories","personal diaries"]},{"contextId":"u2_10_current_affairs_gap_2","answer":"current affairs","wrong":["travel advice","cooking tips","film plots"]},{"contextId":"u2_10_current_affairs_gap_3","answer":"current affairs","wrong":["weather vocabulary","recipe ideas","book characters"]}],"spellingErrors":["curent affairs","current affaires","current afairs","current affares","currant affairs","current affiars"],"masteryPassages":[{"passageId":"u2_10_current_affairs_passage_1","contextId":"u2_10_current_affairs_gap_1","text":"Every morning, Mr Park’s class reads two articles from the newspaper and discusses elections, wars and new laws. He wants students to understand the world beyond school, so ____ is part of his timetable.","answer":"current affairs"},{"passageId":"u2_10_current_affairs_passage_2","contextId":"u2_10_current_affairs_gap_2","text":"Keira wanted to join the debating club, but she knew little about politics. She started listening to a daily podcast on ____ so that she could discuss international issues with confidence.","answer":"current affairs"}],"contextDependentParaphrases":[],"wrongParaphrases":["past events","celebrity gossip","weather forecasts"],"misleadingDistractors":["past events from history","private matters at home","stories from fiction"]}]'::jsonb,'[]'::jsonb,'["follow current affairs","discuss current affairs","international current affairs"]'::jsonb,'live')
