('u2_idea_entertainment',2,'idea_set','{"originalIdea":"The hotel provides live entertainment every evening.","accurateParaphrases":["The hotel offers live shows and music every evening.","Every evening the hotel puts on live performances for its guests.","Guests at the hotel can enjoy live performances each evening."],"meaningInvariants":[{"type":"time","value":"every evening"}],"distractors":[{"text":"The hotel offers live shows only at weekends.","misconceptionCategory":"time_change"},{"text":"The hotel used to offer live shows every evening but has stopped.","misconceptionCategory":"time_change"},{"text":"The hotel provides meals and rooms every evening.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_entertainment"],"primaryEvidenceTargetId":"vocab_entertainment"}'::jsonb,'live'),
('u2_idea_access',2,'idea_set','{"originalIdea":"Pupils in rural areas often lack access to reliable internet.","accurateParaphrases":["Pupils in the countryside often cannot get a dependable internet connection.","Students who live in rural areas frequently have no way of getting reliable internet.","Reliable internet is often unavailable to pupils who live in the countryside."],"meaningInvariants":[{"type":"polarity","value":"reliable internet is not available"}],"distractors":[{"text":"Pupils in the countryside always have a dependable internet connection.","misconceptionCategory":"meaning_confusion"},{"text":"Pupils in cities often cannot get a dependable internet connection.","misconceptionCategory":"meaning_confusion"},{"text":"Pupils in the countryside never want to use the internet.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_access"],"primaryEvidenceTargetId":"vocab_access"}'::jsonb,'live'),
('u2_idea_device',2,'idea_set','{"originalIdea":"Teachers asked students to switch off every device during the exam.","accurateParaphrases":["The teachers told students to turn off all electronic gadgets during the exam.","During the exam, teachers asked for every electronic gadget to be turned off.","Students were told by their teachers to power down all their gadgets while they sat the exam."],"meaningInvariants":[{"type":"quantity","value":"every gadget switched off"}],"distractors":[{"text":"Teachers asked students to switch off only their phones during the exam.","misconceptionCategory":"quantity_change"},{"text":"Teachers asked students to bring an electronic gadget to the exam.","misconceptionCategory":"meaning_confusion"},{"text":"Students switched off every gadget after the exam had finished.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_device"],"primaryEvidenceTargetId":"vocab_device"}'::jsonb,'live'),
('u2_idea_digital',2,'idea_set','{"originalIdea":"The school has replaced printed textbooks with digital ones.","accurateParaphrases":["The school now uses electronic textbooks instead of printed ones.","Electronic textbooks have taken the place of printed books at the school.","Instead of printed textbooks, the school uses electronic versions."],"meaningInvariants":[{"type":"comparison","value":"electronic books instead of printed books"}],"distractors":[{"text":"The school has replaced electronic textbooks with printed ones.","misconceptionCategory":"meaning_confusion"},{"text":"The school uses both electronic and printed textbooks.","misconceptionCategory":"omitted_information"},{"text":"The school plans to replace printed textbooks one day.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_digital"],"primaryEvidenceTargetId":"vocab_digital"}'::jsonb,'live'),
('u2_idea_streaming',2,'idea_set','{"originalIdea":"Streaming has made it easier to watch films without leaving home.","accurateParaphrases":["Watching films over the internet has made it easier to enjoy them without leaving the house.","Viewers can now watch films online from home, which is much easier than before.","It is now easier to watch films at home because they are played over the internet."],"meaningInvariants":[{"type":"cause_effect","value":"online film viewing makes watching at home easier"}],"distractors":[{"text":"Watching films over the internet has made it harder to enjoy them without leaving the house.","misconceptionCategory":"cause_effect_change"},{"text":"Watching films over the internet has made people leave the house to see them.","misconceptionCategory":"cause_effect_change"},{"text":"Films can only be watched at home after they have been downloaded and saved.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_streaming"],"primaryEvidenceTargetId":"vocab_streaming"}'::jsonb,'live'),
('u2_idea_relevant',2,'idea_set','{"originalIdea":"The teacher asked her to remove any details that were not relevant to the question.","accurateParaphrases":["The teacher told her to take out any details that had nothing to do with the question.","She was asked by the teacher to delete details unconnected to the question.","The teacher wanted her to leave out any details that did not relate to the question."],"meaningInvariants":[{"type":"polarity","value":"unconnected details are removed"}],"distractors":[{"text":"The teacher asked her to add more details about the question.","misconceptionCategory":"meaning_confusion"},{"text":"The teacher asked her to keep every detail, even those unconnected to the question.","misconceptionCategory":"meaning_confusion"},{"text":"The teacher asked her to shorten the details that were too long.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_relevant"],"primaryEvidenceTargetId":"vocab_relevant"}'::jsonb,'live'),
('u2_idea_educator',2,'idea_set','{"originalIdea":"Educators from twelve countries attended the conference.","accurateParaphrases":["Teachers from twelve countries went to the conference.","The conference welcomed teachers who had travelled from twelve countries.","People who work as teachers came to the conference from twelve countries."],"meaningInvariants":[{"type":"quantity","value":"twelve countries"}],"distractors":[{"text":"Teachers from only two countries attended the conference.","misconceptionCategory":"quantity_change"},{"text":"Students from twelve countries attended the conference.","misconceptionCategory":"meaning_confusion"},{"text":"Teachers from twelve countries are planning to attend a conference next year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_educator"],"primaryEvidenceTargetId":"vocab_educator"}'::jsonb,'live'),
('u2_idea_afford',2,'idea_set','{"originalIdea":"Few families can afford to replace their devices every year.","accurateParaphrases":["Not many families have enough money to replace their gadgets every year.","Only a small number of families are able to pay for new gadgets each year.","Few families have the money to buy new electronic gadgets every year."],"meaningInvariants":[{"type":"quantity","value":"few families"}],"distractors":[{"text":"Many families can easily replace their gadgets every year.","misconceptionCategory":"quantity_change"},{"text":"Few families want to replace their gadgets every year.","misconceptionCategory":"meaning_confusion"},{"text":"Few families replace their gadgets, but they do so every two years.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_afford_2"],"primaryEvidenceTargetId":"vocab_afford_2"}'::jsonb,'live'),
('u2_idea_essential',2,'idea_set','{"originalIdea":"A reliable internet connection is essential for online lessons.","accurateParaphrases":["Online lessons cannot work without a dependable internet connection.","A dependable internet connection is absolutely necessary for online lessons.","You must have a reliable internet connection to take part in online lessons."],"meaningInvariants":[{"type":"degree","value":"absolutely necessary"}],"distractors":[{"text":"A reliable internet connection is helpful but not necessary for online lessons.","misconceptionCategory":"degree_change"},{"text":"A reliable internet connection is provided free for all online lessons.","misconceptionCategory":"meaning_confusion"},{"text":"A reliable internet connection is only needed after online lessons have finished.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_essential"],"primaryEvidenceTargetId":"vocab_essential"}'::jsonb,'live'),
('u2_idea_current_affairs',2,'idea_set','{"originalIdea":"Students who follow current affairs find it easier to write about global issues.","accurateParaphrases":["Students who keep up with the news find it simpler to write about global issues.","It is easier for students who read about world events to write about global issues.","Students who pay attention to the latest world news can write about global issues more easily."],"meaningInvariants":[{"type":"cause_effect","value":"following the news makes writing easier"}],"distractors":[{"text":"Students who keep up with the news find it harder to write about global issues.","misconceptionCategory":"cause_effect_change"},{"text":"Students who write about global issues find it easier to follow the news.","misconceptionCategory":"cause_effect_change"},{"text":"Students who read old history books find it easier to write about global issues.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_current_affairs"],"primaryEvidenceTargetId":"vocab_current_affairs"}'::jsonb,'live'),
('u2_idea_apparently',2,'idea_set','{"originalIdea":"Apparently, the new teacher used to work as a pilot.","accurateParaphrases":["It seems that the new teacher used to be a pilot.","From what people say, the new teacher used to fly planes for a living.","The new teacher used to work as a pilot, according to what has been said."],"meaningInvariants":[{"type":"degree","value":"reported, not confirmed"}],"distractors":[{"text":"The new teacher is definitely a former pilot, as the school has confirmed.","misconceptionCategory":"degree_change"},{"text":"The new teacher wants to become a pilot.","misconceptionCategory":"meaning_confusion"},{"text":"The new teacher used to teach pilots how to fly.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_apparently"],"primaryEvidenceTargetId":"vocab_apparently"}'::jsonb,'live'),
('u2_idea_supposedly',2,'idea_set','{"originalIdea":"The restaurant is supposedly the best in town, but the food was disappointing.","accurateParaphrases":["People say the restaurant is the best in town, but the food was disappointing.","The restaurant is said to be the best in town, yet the food was disappointing.","The restaurant has a reputation as the best in town, but the food was disappointing."],"meaningInvariants":[{"type":"degree","value":"said to be the best, but doubted"}],"distractors":[{"text":"The restaurant is the best in town, and the food was excellent.","misconceptionCategory":"meaning_confusion"},{"text":"The food was disappointing because the restaurant is not the best in town.","misconceptionCategory":"cause_effect_change"},{"text":"Nobody says the restaurant is the best in town, but the food was good.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_supposedly"],"primaryEvidenceTargetId":"vocab_supposedly"}'::jsonb,'live'),
('u2_idea_celebrity',2,'idea_set','{"originalIdea":"Many teenagers follow a celebrity online and copy the way he dresses.","accurateParaphrases":["Lots of teenagers follow a famous person online and copy his style of clothes.","A large number of teenagers watch a star on the internet and copy what he wears.","Many young people follow a well-known figure on the internet and dress as he does."],"meaningInvariants":[{"type":"quantity","value":"many teenagers"}],"distractors":[{"text":"A few teenagers follow a star online and copy the way he dresses.","misconceptionCategory":"quantity_change"},{"text":"Many teenagers follow a star online but ignore how he dresses.","misconceptionCategory":"omitted_information"},{"text":"Many teenagers dislike a famous person online and refuse to copy him.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_celebrity"],"primaryEvidenceTargetId":"vocab_celebrity"}'::jsonb,'live'),
('u2_idea_informed',2,'idea_set','{"originalIdea":"Voters should make an informed choice before an election.","accurateParaphrases":["Voters should choose carefully after learning the facts before an election.","Before an election, voters ought to base their choice on knowledge of the facts.","Voters need to know the facts before they decide in an election."],"meaningInvariants":[{"type":"time","value":"facts first, then the choice"}],"distractors":[{"text":"Voters should make a quick choice on the day of an election.","misconceptionCategory":"meaning_confusion"},{"text":"Voters should let other people make the choice before an election.","misconceptionCategory":"meaning_confusion"},{"text":"Voters should choose first and learn the facts afterwards.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_informed"],"primaryEvidenceTargetId":"vocab_informed"}'::jsonb,'live'),
('u2_idea_admit',2,'idea_set','{"originalIdea":"The company admitted that the product had a serious fault.","accurateParaphrases":["The company accepted that the product had a serious fault.","The company confessed that the product had a serious fault.","The company agreed that there was a serious fault in its product."],"meaningInvariants":[{"type":"polarity","value":"the fault is accepted as true"}],"distractors":[{"text":"The company denied that the product had a serious fault.","misconceptionCategory":"meaning_confusion"},{"text":"The company warned that the product might have a serious fault.","misconceptionCategory":"degree_change"},{"text":"The company announced that it would improve the product.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_admit"],"primaryEvidenceTargetId":"vocab_admit"}'::jsonb,'live'),
('u2_idea_communicate',2,'idea_set','{"originalIdea":"Some doctors use video calls to communicate with patients in distant villages.","accurateParaphrases":["Some doctors speak to patients in faraway villages through video calls.","Video calls allow some doctors to share information with patients who live in distant villages.","Some doctors stay in touch with patients in far-away villages using video calls."],"meaningInvariants":[{"type":"quantity","value":"some doctors"}],"distractors":[{"text":"All doctors use video calls to speak to patients in distant villages.","misconceptionCategory":"quantity_change"},{"text":"Some doctors travel to distant villages instead of using video calls.","misconceptionCategory":"meaning_confusion"},{"text":"Some doctors use video calls to speak to patients in the same town.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_communicate"],"primaryEvidenceTargetId":"vocab_communicate"}'::jsonb,'live'),
('u2_idea_remotely',2,'idea_set','{"originalIdea":"Many employees now work remotely on Fridays.","accurateParaphrases":["Many employees now work away from the office on Fridays.","On Fridays, many employees now do their jobs from a distance rather than in the office.","Many staff now work from somewhere other than the office on Fridays."],"meaningInvariants":[{"type":"time","value":"on Fridays"}],"distractors":[{"text":"Many employees now work in the office only on Fridays.","misconceptionCategory":"meaning_confusion"},{"text":"Few employees now work away from the office on Fridays.","misconceptionCategory":"quantity_change"},{"text":"Many employees now work away from the office every day except Fridays.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_remotely"],"primaryEvidenceTargetId":"vocab_remotely"}'::jsonb,'live'),
('u2_idea_transform',2,'idea_set','{"originalIdea":"The new library has transformed the town centre.","accurateParaphrases":["The new library has completely changed the town centre.","Because of the new library, the town centre is now very different.","The town centre has become something quite different since the new library was built."],"meaningInvariants":[{"type":"degree","value":"a complete change"}],"distractors":[{"text":"The new library has slightly improved the town centre.","misconceptionCategory":"degree_change"},{"text":"The new library has damaged the town centre.","misconceptionCategory":"meaning_confusion"},{"text":"The town centre has changed the new library.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_transform"],"primaryEvidenceTargetId":"vocab_transform"}'::jsonb,'live'),
('u2_idea_percentage',2,'idea_set','{"originalIdea":"A high percentage of students use their phones to revise.","accurateParaphrases":["A large proportion of students use their phones to revise.","A large share of the students use their phones when they revise.","A big part of the student group uses phones for revision."],"meaningInvariants":[{"type":"quantity","value":"a large part"}],"distractors":[{"text":"A low proportion of students use their phones to revise.","misconceptionCategory":"quantity_change"},{"text":"A high proportion of students own phones but never use them to revise.","misconceptionCategory":"meaning_confusion"},{"text":"Every single student uses a phone to revise.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_percentage"],"primaryEvidenceTargetId":"vocab_percentage"}'::jsonb,'live'),
('u2_idea_impression',2,'idea_set','{"originalIdea":"The new student made a very good impression on her teachers.","accurateParaphrases":["The new student made her teachers think very well of her.","Her teachers formed a very positive opinion of the new student.","The new student left her teachers with a very favourable view of her."],"meaningInvariants":[{"type":"degree","value":"a very positive opinion"}],"distractors":[{"text":"The new student made her teachers think badly of her.","misconceptionCategory":"meaning_confusion"},{"text":"The teachers made a very good impression on the new student.","misconceptionCategory":"cause_effect_change"},{"text":"The new student hardly changed what her teachers thought.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_impression"],"primaryEvidenceTargetId":"vocab_impression"}'::jsonb,'live'),
('u2_idea_remote_control',2,'idea_set','{"originalIdea":"The boy steered the toy car across the garden with a remote control.","accurateParaphrases":["The boy guided the toy car across the garden using a handheld device.","Using a handheld device, the boy made the toy car move across the garden.","The boy drove the toy car around the garden from a distance with a controller."],"meaningInvariants":[{"type":"cause_effect","value":"the boy controls the car"}],"distractors":[{"text":"The toy car steered the boy across the garden.","misconceptionCategory":"cause_effect_change"},{"text":"The boy carried the toy car across the garden.","misconceptionCategory":"meaning_confusion"},{"text":"The boy steered the toy car across the garden by pushing it.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_remote_control"],"primaryEvidenceTargetId":"vocab_remote_control"}'::jsonb,'live'),
('u2_idea_feature',2,'idea_set','{"originalIdea":"The most useful feature of this phone is its long battery life.","accurateParaphrases":["The best thing about this phone is that its battery lasts a long time.","This phone’s most helpful quality is its long-lasting battery.","What makes this phone most useful is a battery that lasts for a long time."],"meaningInvariants":[{"type":"comparison","value":"the most useful"}],"distractors":[{"text":"The least useful thing about this phone is its short battery life.","misconceptionCategory":"polarity_change"},{"text":"The phone is useful because its battery is cheap to replace.","misconceptionCategory":"meaning_confusion"},{"text":"One useful thing about this phone is its long battery life.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_feature"],"primaryEvidenceTargetId":"vocab_feature"}'::jsonb,'live'),
('u2_idea_function',2,'idea_set','{"originalIdea":"The function of a thermostat is to control the temperature in a room.","accurateParaphrases":["A thermostat is made to control the temperature in a room.","The purpose of a thermostat is to keep the temperature of a room under control.","A thermostat does the job of controlling the temperature in a room."],"meaningInvariants":[{"type":"cause_effect","value":"controls the temperature"}],"distractors":[{"text":"A thermostat is made to measure the time in a room.","misconceptionCategory":"meaning_confusion"},{"text":"A thermostat is controlled by the temperature of a room.","misconceptionCategory":"cause_effect_change"},{"text":"A thermostat sometimes controls the temperature in a room.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_function"],"primaryEvidenceTargetId":"vocab_function"}'::jsonb,'live'),
('u2_idea_interactive',2,'idea_set','{"originalIdea":"Students enjoy the interactive displays in the science museum.","accurateParaphrases":["Students enjoy the displays in the science museum that they can touch and respond to.","In the science museum, students like the displays that react to what they do.","The science museum has displays that students can take part in, and they enjoy them."],"meaningInvariants":[{"type":"polarity","value":"students like the displays"}],"distractors":[{"text":"Students dislike the interactive displays in the science museum.","misconceptionCategory":"meaning_confusion"},{"text":"Students enjoy the displays in the science museum but cannot touch them.","misconceptionCategory":"omitted_information"},{"text":"Students enjoy the museum shop in the science museum.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_interactive"],"primaryEvidenceTargetId":"vocab_interactive"}'::jsonb,'live'),
('u2_idea_widespread',2,'idea_set','{"originalIdea":"Flooding was widespread across the north of the country last winter.","accurateParaphrases":["Flooding affected many parts of the north of the country last winter.","Last winter, floods covered large areas across the north of the country.","Last winter, the north of the country was hit by floods in many places."],"meaningInvariants":[{"type":"quantity","value":"many places"}],"distractors":[{"text":"Flooding affected only one village in the north last winter.","misconceptionCategory":"quantity_change"},{"text":"Flooding was widespread across the south of the country last winter.","misconceptionCategory":"meaning_confusion"},{"text":"Flooding was widespread in the north last summer.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_widespread"],"primaryEvidenceTargetId":"vocab_widespread"}'::jsonb,'live'),
('u2_idea_availability',2,'idea_set','{"originalIdea":"The availability of fresh fruit improves in the summer months.","accurateParaphrases":["It is easier to get fresh fruit in the summer months.","In the summer months, fresh fruit becomes easier to find.","During summer, there is more fresh fruit to buy."],"meaningInvariants":[{"type":"time","value":"in the summer months"}],"distractors":[{"text":"Fresh fruit becomes harder to find in the summer months.","misconceptionCategory":"degree_change"},{"text":"The price of fresh fruit improves in the summer months.","misconceptionCategory":"meaning_confusion"},{"text":"It is easier to get fresh fruit in the winter months.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_availability"],"primaryEvidenceTargetId":"vocab_availability"}'::jsonb,'live'),
('u2_idea_high_performance',2,'idea_set','{"originalIdea":"Professional cyclists ride high-performance bikes in major races.","accurateParaphrases":["Professional cyclists ride very fast, powerful bikes in major races.","In major races, professional cyclists use bikes built for top speed.","Top cyclists use specially built, powerful bikes in important races."],"meaningInvariants":[{"type":"degree","value":"top level"}],"distractors":[{"text":"Professional cyclists ride cheap bikes in major races.","misconceptionCategory":"meaning_confusion"},{"text":"Some cyclists ride high-quality bikes in small races.","misconceptionCategory":"quantity_change"},{"text":"Professional cyclists ride slightly faster bikes in major races.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_high_performance"],"primaryEvidenceTargetId":"vocab_high_performance"}'::jsonb,'live'),
('u2_idea_stabilising',2,'idea_set','{"originalIdea":"The new manager has had a stabilising effect on the team.","accurateParaphrases":["The new manager has made the team steadier.","Since the new manager arrived, the team has become more settled.","The team has become calmer and more settled because of the new manager."],"meaningInvariants":[{"type":"cause_effect","value":"the manager causes the change"}],"distractors":[{"text":"The team has had a stabilising effect on the new manager.","misconceptionCategory":"cause_effect_change"},{"text":"The new manager has made the team more nervous.","misconceptionCategory":"meaning_confusion"},{"text":"The new manager has had a small effect on the team.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_stabilising"],"primaryEvidenceTargetId":"vocab_stabilising"}'::jsonb,'live'),
('u2_idea_multi_task',2,'idea_set','{"originalIdea":"Few people can multi-task effectively while they study.","accurateParaphrases":["Few people can do several jobs well at the same time while they study.","Only a small number of people manage to do many things at once while studying.","It is difficult for most people to study well while doing other things at the same time."],"meaningInvariants":[{"type":"quantity","value":"few people"}],"distractors":[{"text":"Many people can do several jobs well at the same time while they study.","misconceptionCategory":"quantity_change"},{"text":"Few people can study for a long time.","misconceptionCategory":"meaning_confusion"},{"text":"Few people can study well at night.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_multi_task"],"primaryEvidenceTargetId":"vocab_multi_task"}'::jsonb,'live'),
('u2_idea_predictable',2,'idea_set','{"originalIdea":"The ending of the story was entirely predictable.","accurateParaphrases":["Everyone could guess the ending of the story.","It was easy to guess how the story would end.","The story’s ending was exactly what readers expected."],"meaningInvariants":[{"type":"degree","value":"completely"}],"distractors":[{"text":"The ending of the story was partly predictable.","misconceptionCategory":"degree_change"},{"text":"The ending of the story was impossible to guess.","misconceptionCategory":"meaning_confusion"},{"text":"The ending of the story was predictable, but the beginning was not.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_predictable"],"primaryEvidenceTargetId":"vocab_predictable"}'::jsonb,'live'),
('u2_idea_professional',2,'idea_set','{"originalIdea":"Many professional athletes stop competing before they are forty.","accurateParaphrases":["Many people who earn their living from sport stop competing before the age of forty.","A large number of full-time sportspeople end their careers before they turn forty.","Lots of athletes who are paid to compete retire before they reach forty."],"meaningInvariants":[{"type":"quantity","value":"many"}],"distractors":[{"text":"A few people who earn their living from sport stop competing before the age of forty.","misconceptionCategory":"quantity_change"},{"text":"Many amateur athletes begin competing after they are forty.","misconceptionCategory":"meaning_confusion"},{"text":"Many people who earn their living from sport start competing before the age of forty.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_professional"],"primaryEvidenceTargetId":"vocab_professional"}'::jsonb,'live'),
('u2_idea_regional',2,'idea_set','{"originalIdea":"Regional newspapers have lost many readers over the last ten years.","accurateParaphrases":["Newspapers that cover one part of the country have lost many readers over the last ten years.","Over the last decade, papers serving a single area have lost a large number of readers.","In the past ten years, many readers have stopped buying papers that report on one area of the country."],"meaningInvariants":[{"type":"time","value":"over the last ten years"}],"distractors":[{"text":"Newspapers that cover the whole country have lost many readers over the last ten years.","misconceptionCategory":"meaning_confusion"},{"text":"Newspapers that cover one part of the country have gained many readers over the last ten years.","misconceptionCategory":"polarity_change"},{"text":"Newspapers that cover one part of the country lost a few readers last year.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_regional"],"primaryEvidenceTargetId":"vocab_regional"}'::jsonb,'live'),
('u2_idea_commentary',2,'idea_set','{"originalIdea":"The radio commentary made the match sound more exciting than it really was.","accurateParaphrases":["The spoken description on the radio made the match seem more exciting than it was.","Listeners on the radio heard a description that made the match sound better than it really was.","The match was not as exciting as the radio description made it sound."],"meaningInvariants":[{"type":"comparison","value":"more exciting than in reality"}],"distractors":[{"text":"The radio commentary made the match sound less exciting than it really was.","misconceptionCategory":"polarity_change"},{"text":"The match was even more exciting than the radio commentary made it sound.","misconceptionCategory":"comparison_change"},{"text":"The radio made the match sound more exciting because it played music.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_commentary"],"primaryEvidenceTargetId":"vocab_commentary"}'::jsonb,'live'),
('u2_idea_educational',2,'idea_set','{"originalIdea":"The museum runs educational workshops for school groups every Friday.","accurateParaphrases":["Every Friday, the museum holds workshops where school groups learn new things.","School groups can join workshops at the museum each Friday that are designed to teach them.","The museum offers learning workshops for school groups every week on a Friday."],"meaningInvariants":[{"type":"time","value":"every Friday"}],"distractors":[{"text":"The museum runs workshops for school groups on one Friday each year.","misconceptionCategory":"time_change"},{"text":"The museum runs workshops for adults every Friday to teach them to paint.","misconceptionCategory":"meaning_confusion"},{"text":"The museum runs entertaining shows for school groups every Friday.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_educational"],"primaryEvidenceTargetId":"vocab_educational"}'::jsonb,'live'),
('u2_idea_culture',2,'idea_set','{"originalIdea":"Learning a language helps you understand the culture of the people who speak it.","accurateParaphrases":["Learning a language helps you understand the way of life of the people who speak it.","If you learn their language, you can better understand the customs and beliefs of its speakers.","Studying a language gives you a better understanding of how its speakers live and what they believe."],"meaningInvariants":[{"type":"cause_effect","value":"learning a language leads to understanding"}],"distractors":[{"text":"Understanding the way of life of a people helps you learn their language.","misconceptionCategory":"cause_effect_change"},{"text":"Learning a language makes it harder to understand the people who speak it.","misconceptionCategory":"meaning_confusion"},{"text":"Learning a language guarantees that you will visit the country where it is spoken.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_culture"],"primaryEvidenceTargetId":"vocab_culture"}'::jsonb,'live'),
('u2_idea_genuine',2,'idea_set','{"originalIdea":"The inspector checked that the painting was genuine before the museum bought it.","accurateParaphrases":["The inspector made sure the painting was real before the museum bought it.","Before buying the painting, the museum had an inspector confirm that it was not a fake.","The museum bought the painting only after the inspector had checked that it was authentic."],"meaningInvariants":[{"type":"time","value":"before it was bought"}],"distractors":[{"text":"The inspector checked that the painting was real after the museum bought it.","misconceptionCategory":"time_change"},{"text":"The inspector checked that the painting was valuable before the museum bought it.","misconceptionCategory":"meaning_confusion"},{"text":"The museum bought the painting without asking the inspector.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_genuine"],"primaryEvidenceTargetId":"vocab_genuine"}'::jsonb,'live'),
('u2_idea_amusing',2,'idea_set','{"originalIdea":"Most students found the headteacher’s speech mildly amusing.","accurateParaphrases":["Most students thought the headteacher’s speech was slightly funny.","The majority of students smiled a little at the headteacher’s speech.","For most students, the headteacher’s speech was a little entertaining."],"meaningInvariants":[{"type":"degree","value":"mildly"}],"distractors":[{"text":"Most students found the headteacher’s speech extremely amusing.","misconceptionCategory":"degree_change"},{"text":"Few students found the headteacher’s speech mildly amusing.","misconceptionCategory":"quantity_change"},{"text":"Most students found the headteacher’s speech slightly boring.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_amusing"],"primaryEvidenceTargetId":"vocab_amusing"}'::jsonb,'live'),
('u2_idea_competitive',2,'idea_set','{"originalIdea":"The mobile phone industry has become far more competitive in recent years.","accurateParaphrases":["Far more companies now try hard to win customers in the mobile phone industry than in the past.","In recent years, mobile phone firms have started to compete much more strongly.","Competition between mobile phone companies has grown a great deal recently."],"meaningInvariants":[{"type":"time","value":"in recent years"}],"distractors":[{"text":"The mobile phone industry has become slightly more competitive in recent years.","misconceptionCategory":"degree_change"},{"text":"The mobile phone industry has become far less competitive in recent years.","misconceptionCategory":"polarity_change"},{"text":"Mobile phone companies have become far more profitable in recent years.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_competitive"],"primaryEvidenceTargetId":"vocab_competitive"}'::jsonb,'live'),
('u2_idea_critical',2,'idea_set','{"originalIdea":"The inspector was critical of the way the school kept its records.","accurateParaphrases":["The inspector said that the school’s record-keeping had faults.","The inspector disapproved of how the school kept its records.","The inspector found problems in the way the school looked after its records."],"meaningInvariants":[{"type":"polarity","value":"disapproval"}],"distractors":[{"text":"The inspector praised the way the school kept its records.","misconceptionCategory":"meaning_confusion"},{"text":"The inspector was surprised by how many records the school kept.","misconceptionCategory":"meaning_confusion"},{"text":"The inspector thought the school’s records were very important.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_critical"],"primaryEvidenceTargetId":"vocab_critical"}'::jsonb,'live'),
('u2_idea_impressive',2,'idea_set','{"originalIdea":"Her exam results were impressive, especially in mathematics.","accurateParaphrases":["Her exam results were excellent, particularly in mathematics.","She got very good exam results, and the best were in mathematics.","Her results in the exams were remarkable, most of all in mathematics."],"meaningInvariants":[{"type":"degree","value":"very good"}],"distractors":[{"text":"Her exam results were average, except in mathematics.","misconceptionCategory":"degree_change"},{"text":"Her exam results were impressive, but not in mathematics.","misconceptionCategory":"omitted_information"},{"text":"Her mathematics results were better than her other results.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_impressive"],"primaryEvidenceTargetId":"vocab_impressive"}'::jsonb,'live'),
('u2_idea_determination',2,'idea_set','{"originalIdea":"Her determination to win a place at university never weakened.","accurateParaphrases":["She never lost her strong will to win a place at university.","She kept her firm resolve to get into university throughout.","Her strong wish to win a place at university stayed just as firm."],"meaningInvariants":[{"type":"polarity","value":"it never weakened"}],"distractors":[{"text":"Her determination to win a place at university weakened over time.","misconceptionCategory":"polarity_change"},{"text":"Her family’s determination to win a place at university never weakened.","misconceptionCategory":"meaning_confusion"},{"text":"She won a place at university without trying.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_determination"],"primaryEvidenceTargetId":"vocab_determination"}'::jsonb,'live'),
('u2_idea_overcome',2,'idea_set','{"originalIdea":"He overcame his fear of speaking in public by practising every week.","accurateParaphrases":["He got past his fear of speaking in public by practising each week.","Weekly practice helped him beat his fear of public speaking.","By practising every week, he dealt successfully with his fear of speaking in front of people."],"meaningInvariants":[{"type":"cause_effect","value":"practice caused success"}],"distractors":[{"text":"He avoided speaking in public because he practised every week.","misconceptionCategory":"cause_effect_change"},{"text":"He still fears speaking in public, although he practises every week.","misconceptionCategory":"polarity_change"},{"text":"He overcame his fear of heights by practising every week.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_overcome"],"primaryEvidenceTargetId":"vocab_overcome"}'::jsonb,'live'),
('u2_idea_accessory',2,'idea_set','{"originalIdea":"The most popular accessory in the shop is a protective phone case.","accurateParaphrases":["The extra item that sells best in the shop is a protective phone case.","In the shop, customers buy a protective case for their phone more often than any other extra.","A protective phone case is the best-selling extra in the shop."],"meaningInvariants":[{"type":"comparison","value":"the most popular"}],"distractors":[{"text":"The least popular extra item in the shop is a protective phone case.","misconceptionCategory":"polarity_change"},{"text":"One popular extra item in the shop is a protective phone case.","misconceptionCategory":"degree_change"},{"text":"The most popular phone in the shop has a protective case.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_accessory"],"primaryEvidenceTargetId":"vocab_accessory"}'::jsonb,'live'),
('u2_idea_equipment',2,'idea_set','{"originalIdea":"The school must replace its old science equipment before next term.","accurateParaphrases":["The school has to buy new science tools and machines before the next term.","Before next term, the school needs to get rid of its old laboratory apparatus and replace it.","The science department needs new tools to take the place of the old ones by next term."],"meaningInvariants":[{"type":"time","value":"before next term"}],"distractors":[{"text":"The school may replace its old science equipment after next term.","misconceptionCategory":"time_change"},{"text":"The school must repair its old science equipment before next term.","misconceptionCategory":"meaning_confusion"},{"text":"The school must replace its old teachers before next term.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_equipment"],"primaryEvidenceTargetId":"vocab_equipment"}'::jsonb,'live'),
('u2_idea_fixture',2,'idea_set','{"originalIdea":"In this flat, the kitchen units are fixtures, so the tenant cannot take them away.","accurateParaphrases":["In this flat, the kitchen units are permanently fitted, so the tenant cannot remove them.","The tenant must leave the kitchen units in the flat because they are permanently attached to it.","The kitchen units are part of the flat, so the tenant is not allowed to take them away."],"meaningInvariants":[{"type":"cause_effect","value":"because they are permanent"}],"distractors":[{"text":"In this flat, the kitchen units belong to the tenant, so he can take them away.","misconceptionCategory":"polarity_change"},{"text":"In this flat, the tenant cannot take the kitchen units away because he has not paid for them.","misconceptionCategory":"cause_effect_change"},{"text":"In this flat, only some of the kitchen units are permanently fitted.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_fixture"],"primaryEvidenceTargetId":"vocab_fixture"}'::jsonb,'live'),
('u2_idea_removable',2,'idea_set','{"originalIdea":"The headphones have removable ear pads, which makes them easy to clean.","accurateParaphrases":["The ear pads on the headphones can be taken off, so cleaning them is easy.","Because the headphones’ ear pads come off, they are easy to clean.","Taking the ear pads off the headphones makes cleaning simple."],"meaningInvariants":[{"type":"cause_effect","value":"being detachable makes cleaning easy"}],"distractors":[{"text":"The ear pads on the headphones cannot be taken off, so cleaning them is difficult.","misconceptionCategory":"polarity_change"},{"text":"The headphones are easy to clean because they are waterproof.","misconceptionCategory":"cause_effect_change"},{"text":"The ear pads can be taken off, but they are hard to clean.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_removable"],"primaryEvidenceTargetId":"vocab_removable"}'::jsonb,'live'),
('u2_idea_adjustable',2,'idea_set','{"originalIdea":"The adjustable desk can be raised or lowered to suit students of any height.","accurateParaphrases":["The desk can be moved up or down to fit students of any height.","Students of any height can use the desk because its height can be changed.","The desk’s height can be changed so that every student can work comfortably."],"meaningInvariants":[{"type":"quantity","value":"students of any height"}],"distractors":[{"text":"The desk can be raised or lowered, but only for tall students.","misconceptionCategory":"quantity_change"},{"text":"The desk is fixed at one height that suits all students.","misconceptionCategory":"polarity_change"},{"text":"The desk can be folded away when students are not using it.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_adjustable"],"primaryEvidenceTargetId":"vocab_adjustable"}'::jsonb,'live'),
('u2_idea_affordable',2,'idea_set','{"originalIdea":"The council wants more affordable homes for young families.","accurateParaphrases":["The council wants more homes that young families can pay for.","The council would like to provide more houses at prices young families can manage.","More homes at reasonable prices for young families are what the council wants."],"meaningInvariants":[{"type":"quantity","value":"more homes"}],"distractors":[{"text":"The council wants fewer homes for young families.","misconceptionCategory":"quantity_change"},{"text":"The council wants more luxury homes for young families.","misconceptionCategory":"meaning_confusion"},{"text":"The council wants more homes for older people to buy.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_affordable"],"primaryEvidenceTargetId":"vocab_affordable"}'::jsonb,'live'),
('u2_idea_external',2,'idea_set','{"originalIdea":"Marks for the project are checked by an external examiner.","accurateParaphrases":["A person from outside the school checks the marks for the project.","An examiner who does not work at the school checks the project marks.","The project marks are checked by someone from another organisation."],"meaningInvariants":[{"type":"cause_effect","value":"checked by an outsider"}],"distractors":[{"text":"Marks for the project are checked by the class teacher.","misconceptionCategory":"meaning_confusion"},{"text":"Marks for the project are changed by an external examiner.","misconceptionCategory":"cause_effect_change"},{"text":"Marks for the project are checked by a computer.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_external"],"primaryEvidenceTargetId":"vocab_external"}'::jsonb,'live'),
('u2_idea_concentrate',2,'idea_set','{"originalIdea":"Students often find it hard to concentrate when their phones are nearby.","accurateParaphrases":["Students often struggle to focus when their phones are close.","It is often difficult for students to give full attention to their work with a phone nearby.","Having a phone close makes it hard for students to pay attention."],"meaningInvariants":[{"type":"polarity","value":"it is hard"}],"distractors":[{"text":"Students often find it easy to concentrate when their phones are nearby.","misconceptionCategory":"polarity_change"},{"text":"Students rarely find it hard to concentrate when their phones are nearby.","misconceptionCategory":"quantity_change"},{"text":"Students often find it hard to concentrate when their phones are switched off.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_concentrate"],"primaryEvidenceTargetId":"vocab_concentrate"}'::jsonb,'live'),
('u2_writing_precision_entertainment_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “things to watch and play for fun” with a more precise Unit 2 word or phrase.","sourceText":"The cruise ship provides plenty of things to watch and play for fun every night.","acceptedAnswers":["entertainment"],"distractors":["equipment","transport","accommodation"],"linkedVocabularyIds":["vocab_entertainment"],"primaryEvidenceTargetId":"vocab_entertainment"}'::jsonb,'live'),
('u2_writing_precision_entertainment_b',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “fun” with a more precise Unit 2 word or phrase.","sourceText":"For many families, games and films are a source of fun on rainy weekends.","acceptedAnswers":["entertainment"],"distractors":["income","pollution","exercise"],"linkedVocabularyIds":["vocab_entertainment"],"primaryEvidenceTargetId":"vocab_entertainment"}'::jsonb,'live'),
('u2_writing_precision_access_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “the ability to get into” with a more precise Unit 2 word or phrase.","sourceText":"Disabled visitors need the ability to get into every part of the museum.","acceptedAnswers":["access to"],"distractors":["a map of","a guide to","a fee for"],"linkedVocabularyIds":["vocab_access"],"primaryEvidenceTargetId":"vocab_access"}'::jsonb,'live'),
('u2_writing_precision_access_b',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “the right to use” with a more precise Unit 2 word or phrase.","sourceText":"Library members have the right to use the online database for free.","acceptedAnswers":["access to"],"distractors":["a fee for","a ban on","a guide to"],"linkedVocabularyIds":["vocab_access"],"primaryEvidenceTargetId":"vocab_access"}'::jsonb,'live'),
('u2_writing_precision_device_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “small electronic machine” with a more precise Unit 2 word or phrase.","sourceText":"Most teenagers carry at least one small electronic machine in their pockets.","acceptedAnswers":["device"],"distractors":["charger","cable","battery"],"linkedVocabularyIds":["vocab_device"],"primaryEvidenceTargetId":"vocab_device"}'::jsonb,'live'),
