('u2_writing_precision_digital_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “electronic” with a more precise Unit 2 word or phrase.","sourceText":"Many schools now provide electronic textbooks instead of printed ones.","acceptedAnswers":["digital"],"distractors":["historic","handwritten","secondhand"],"linkedVocabularyIds":["vocab_digital"],"primaryEvidenceTargetId":"vocab_digital"}'::jsonb,'live'),
