('u2_writing_precision_streaming_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “watching films online” with a more precise Unit 2 word or phrase.","sourceText":"Among teenagers, watching films online is now more common than going to the cinema.","acceptedAnswers":["streaming films","streaming"],"distractors":["downloading films","recording films","buying films"],"linkedVocabularyIds":["vocab_streaming"],"primaryEvidenceTargetId":"vocab_streaming"}'::jsonb,'live'),
('u2_writing_precision_streaming_b',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “playing music over the internet” with a more precise Unit 2 word or phrase.","sourceText":"A fast connection is needed for playing music over the internet without delays.","acceptedAnswers":["streaming music","streaming"],"distractors":["recording music","composing music","selling music"],"linkedVocabularyIds":["vocab_streaming"],"primaryEvidenceTargetId":"vocab_streaming"}'::jsonb,'live'),
('u2_writing_precision_relevant_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “connected” with a more precise Unit 2 word or phrase.","sourceText":"Only include examples that are connected to the question.","acceptedAnswers":["relevant"],"distractors":["similar","equal","familiar"],"linkedVocabularyIds":["vocab_relevant"],"primaryEvidenceTargetId":"vocab_relevant"}'::jsonb,'live'),
('u2_writing_precision_relevant_b',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “useful and on topic” with a more precise Unit 2 word or phrase.","sourceText":"Choose evidence that is useful and on topic for your argument.","acceptedAnswers":["relevant"],"distractors":["recent","famous","lengthy"],"linkedVocabularyIds":["vocab_relevant"],"primaryEvidenceTargetId":"vocab_relevant"}'::jsonb,'live'),
('u2_writing_precision_educator_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “teacher” with a more precise Unit 2 word or phrase.","sourceText":"The school hired an experienced teacher to lead the new course.","acceptedAnswers":["educator"],"distractors":["inspector","librarian","caretaker"],"linkedVocabularyIds":["vocab_educator"],"primaryEvidenceTargetId":"vocab_educator"}'::jsonb,'live'),
('u2_writing_precision_educator_b',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “teachers and trainers” with a more precise Unit 2 word or phrase.","sourceText":"Conferences let teachers and trainers share new ideas.","acceptedAnswers":["educators"],"distractors":["inspectors","parents","politicians"],"linkedVocabularyIds":["vocab_educator"],"primaryEvidenceTargetId":"vocab_educator"}'::jsonb,'live'),
('u2_writing_precision_afford_a',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “do not have enough money to pay for” with a more precise Unit 2 word or phrase.","sourceText":"Many families do not have enough money to pay for a new tablet each year.","acceptedAnswers":["cannot afford"],"distractors":["cannot borrow","cannot repair","cannot choose"],"linkedVocabularyIds":["vocab_afford_2"],"primaryEvidenceTargetId":"vocab_afford_2"}'::jsonb,'live'),
('u2_writing_precision_afford_b',2,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “has enough money for” with a more precise Unit 2 word or phrase.","sourceText":"The school has enough money for a new set of laptops this term.","acceptedAnswers":["can afford"],"distractors":["can borrow","can refuse","can repair"],"linkedVocabularyIds":["vocab_afford_2"],"primaryEvidenceTargetId":"vocab_afford_2"}'::jsonb,'live'),
